class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def reduce_text(text: str) -> str:
            chars = list(text)
            changed = True
            while changed:
                changed = False
                for i, ch in enumerate(chars):
                    if ch == "#":
                        start = i - 1 if i > 0 else i
                        del chars[start:i + 1]
                        changed = True
                        break
            return "".join(chars)

        return reduce_text(s) == reduce_text(t)

