class Solution:
    def backspaceCompare(self, s: str, t: str) -> bool:
        def next_valid(text: str, i: int) -> int:
            skip = 0
            while i >= 0:
                if text[i] == "#":
                    skip += 1
                    i -= 1
                elif skip:
                    skip -= 1
                    i -= 1
                else:
                    break
            return i

        i, j = len(s) - 1, len(t) - 1
        while i >= 0 or j >= 0:
            i = next_valid(s, i)
            j = next_valid(t, j)
            if i < 0 or j < 0:
                return i == j
            if s[i] != t[j]:
                return False
            i -= 1
            j -= 1
        return True

